theorem Forall₂.append_inv {R : α → α → Prop} {xs₁ xs₂ ys₁ ys₂ : List α}
    (h : Forall₂ R (xs₁ ++ ys₁) (xs₂ ++ ys₂)) (hlen : xs₁.length = xs₂.length) :
    Forall₂ R xs₁ xs₂ ∧ Forall₂ R ys₁ ys₂

theorem wotsChecksumValue_le {digits : List ℕ} {w l1 : ℕ}
    (hLen : digits.length = l1) (hBound : ∀ d ∈ digits, d < w) :
    wotsChecksumValue w digits ≤ l1 * (w - 1)

theorem inverseStageRev_eq {Pair : Type v} {Coord : Type w}
    (layout : ButterflyLayout Pair Coord) (zRev : Pair → R) :
    inverseStageRev layout zRev = inverseStage layout (fun pair => -zRev pair)

theorem centeredRepr_intCast_eq_of_natAbs_le (z : ℤ) {b : ℕ}
    (hbound : z.natAbs ≤ b) (hbq : 2 * b < q) :
    centeredRepr ((z : ZMod q)) = z

@[grind =]
lemma liftM_def {m : Type u → Type v} [Monad m] {α : Type u}
    (x : m α) : (x : OptionT m α) = OptionT.lift x

@[aesop (rule_sets := [finiteness]) safe apply]
protected theorem Finiteness.sum_ne_top {ι : Type*} {s : Finset ι} {f : ι → ℝ≥0∞}
    (h : ∀ a ∈ s, f a ≠ ∞) : ∑ a ∈ s, f a ≠ ∞

lemma sq_sum_div_card_le_sum_sq {ι' : Type*}
    (s : Finset ι') (f : ι' → ℝ≥0∞) :
    (∑ i ∈ s, f i) ^ 2 / (s.card : ℝ≥0∞) ≤ ∑ i ∈ s, f i ^ 2

lemma sq_sum_le_card_mul_sum_sq {ι' : Type*}
    (s : Finset ι') (f : ι' → ℝ≥0∞) :
    (∑ i ∈ s, f i) ^ 2 ≤ s.card * ∑ i ∈ s, f i ^ 2

@[simp]
theorem get_update_of_ne [DecidableEq Ident] {h : Heap Ident} {i j : Ident}
    (hij : j ≠ i) (v : CellSpec.type i) : (h.update i v).get j = h.get j

theorem FullData.map_getRootValue {α β : Type _} {s : Skeleton}
    (f : α → β) (tree : FullData α s) :
    (tree.map f).getRootValue = f (tree.getRootValue)

theorem SkeletonNodeIndex.leftChild_bind_parent {s : Skeleton}
    (idx : SkeletonNodeIndex s) :
    idx.leftChild >>= parent = idx.leftChild.map (fun _ => idx)

theorem SkeletonNodeIndex.parent_of_depth_zero {s : Skeleton}
    (idx : SkeletonNodeIndex s) (h : idx.depth = 0) :
    parent idx = none

theorem SkeletonNodeIndex.rightChild_bind_parent {s : Skeleton}
    (idx : SkeletonNodeIndex s) :
    idx.rightChild >>= parent = idx.rightChild.map (fun _ => idx)

lemma mapM_id_some_index
    {α : Type} {L : ℕ} {v : Vector (Option α) L} {w : Vector α L}
    (h : v.mapM id = some w) (i : Fin L) : v[i] = some w[i]

@[simp]
lemma heq_of_toArray_eq_of_size_eq {α} {m n : ℕ} {a : Vector α m} {b : Vector α n}
    (h : a.toArray = b.toArray) (h' : m = n) : HEq a b

lemma List.Vector.card_eq_count {α : Type} [DecidableEq α] {n : ℕ}
    (xs : List.Vector α n) (x : α) :
    ({i : Fin n | x = xs.get i} : Finset (Fin n)).card = xs.toList.count x

theorem measurable_elim [MeasurableSpace α] [MeasurableSpace β] {f : Option α → β}
    (hNone : Measurable (fun _ : Unit => f none))
    (hSome : Measurable (f ∘ some)) : Measurable f

theorem dropNone_apply_singleton [MeasurableSingletonClass α]
    (μ : Measure (Option α)) (x : α) :
    dropNone μ {x} = μ {some x}

@[simp]
lemma PMF.monad_bind_eq_bind {α β : Type u}
      (p : PMF α) (q : α → PMF β) : p >>= q = p.bind q

theorem tsum_coe_mul_nat_le_tsum_of_measure_Ioi_le (p : PMF ℕ) {a : ℕ → ℝ≥0∞}
    (h : ∀ i : ℕ, p.toMeasure (Set.Ioi i) ≤ a i) :
    (∑' n : ℕ, p n * (n : ℝ≥0∞)) ≤ ∑' i : ℕ, a i

theorem IsCoupling.apply_eq_zero_of_pure_left {α β : Type u} {a : α} {q : SPMF β}
    {c : SPMF (α × β)} (hc : IsCoupling c (pure a) q) {x : α} (b : β) (hxa : x ≠ a) :
    c (x, b) = 0

theorem IsCoupling.apply_eq_zero_of_pure_right {α β : Type u} {p : SPMF α} {b : β}
    {c : SPMF (α × β)} (hc : IsCoupling c p (pure b)) (a : α) {y : β} (hyb : y ≠ b) :
    c (a, y) = 0

theorem IsCoupling.apply_pure_left_eq {α β : Type u} {a : α} {q : SPMF β}
    {c : SPMF (α × β)} (hc : IsCoupling c (pure a) q) (b : β) :
    c (a, b) = q b

theorem IsCoupling.apply_pure_right_eq {α β : Type u} {p : SPMF α} {b : β}
    {c : SPMF (α × β)} (hc : IsCoupling c p (pure b)) (a : α) :
    c (a, b) = p a

theorem IsCoupling.bind {α₁ α₂ β₁ β₂ : Type u}
    {p : SPMF α₁} {q : SPMF α₂} {f : α₁ → SPMF β₁} {g : α₂ → SPMF β₂}
    (c : Coupling p q) (d : (a₁ : α₁) → (a₂ : α₂) → SPMF (β₁ × β₂))
    (h : ∀ (a₁ : α₁) (a₂ : α₂), c.1.1 (some (a₁, a₂)) ≠ 0 → IsCoupling (d a₁ a₂) (f a₁) (g a₂)) :
    IsCoupling (c.1 >>= fun (p : α₁ × α₂) => d p.1 p.2) (p >>= f) (q >>= g)

theorem IsCoupling.dirac_left {α β : Type u} (a : α) {q : SPMF β}
    (hq : q.toPMF none = 0) :
    IsCoupling (((a, ·) : β → α × β) <$> q) (pure a) q

theorem IsCoupling.exists_bind {α₁ α₂ β₁ β₂ : Type u}
    {p : SPMF α₁} {q : SPMF α₂} {f : α₁ → SPMF β₁} {g : α₂ → SPMF β₂}
    (c : Coupling p q)
    (h : ∀ (a₁ : α₁) (a₂ : α₂), ∃ (d : SPMF (β₁ × β₂)), IsCoupling d (f a₁) (g a₂)) :
    ∃ (d : SPMF (β₁ × β₂)), IsCoupling d (p >>= f) (q >>= g)

theorem IsCoupling.prod {α β : Type u} {p : SPMF α} {q : SPMF β}
    (hp : p.toPMF none = 0) (hq : q.toPMF none = 0) :
    IsCoupling (p >>= fun a => q >>= fun b => pure (a, b)) p q

theorem IsCoupling.tsum_pure_left {α β : Type u} {a : α} {q : SPMF β}
    {c : SPMF (α × β)} (hc : IsCoupling c (pure a) q) (g : α → β → ℝ≥0∞) :
    ∑' z : α × β, c z * g z.1 z.2 = ∑' b, q b * g a b

theorem IsCoupling.tsum_pure_right {α β : Type u} {p : SPMF α} {b : β}
    {c : SPMF (α × β)} (hc : IsCoupling c p (pure b)) (g : α → β → ℝ≥0∞) :
    ∑' z : α × β, c z * g z.1 z.2 = ∑' a, p a * g a b

lemma SameDist.bind_congr {p q : Raw α}
    {f g : α → Raw β} (hpq : SameDist p q) (hfg : ∀ x, SameDist (f x) (g x)) :
    SameDist (p >>= f) (q >>= g)

lemma SameDist.map_congr {p q : Raw α}
    (hpq : SameDist p q) (f : α → β) :
    SameDist (f <$> p) (f <$> q)

theorem negligible_ofReal_sum {ι : Type*} {s : Finset ι} {ε : ι → ℕ → ℝ}
    (h : ∀ i ∈ s, negligible fun n => ENNReal.ofReal (ε i n)) :
    negligible fun n => ENNReal.ofReal (∑ i ∈ s, ε i n)

theorem negligible_sum {ι : Type*} {s : Finset ι} {f : ι → ℕ → ℝ≥0∞}
    (h : ∀ i ∈ s, negligible (f i)) :
    negligible (fun n => ∑ i ∈ s, f i n)
